"""Build the audit deliverables from completed, version-matched evidence."""
from pathlib import Path
import hashlib
import html
import json

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/audit-fonctionnel-2026-11-15'
def read(name): return json.loads((OUT/name).read_text(encoding='utf-8'))
dom=read('dom-after.json')
reg=read('regressions.json')
targeted=read('targeted-retest.json') if (OUT/'targeted-retest.json').exists() else []
media=read('media.json')
browser=read('browser-summary.json')
assert len(dom['pages'])==3, 'Le parcours complet est encore en cours.'
for p in dom['pages']:
 assert not p['errors'] and not p['missingAudio'] and not p.get('brokenDestinations')
 assert not any(r.get('error') or r.get('missing') for r in p['routes'])
 assert all(f['ok'] for f in p['fetches'])
 assert hashlib.sha256((ROOT/p['file']).read_bytes()).hexdigest()==p['testedHash'], 'Le fichier a changé depuis son contrôle : '+p['file']
 prior=next(r for r in reg['pages'] if r['file']==p['file'])
 assert prior['testedHash']==p['testedHash'] or any(r['file']==p['file'] and r['testedHash']==p['testedHash'] for r in targeted)
assert not media['missingReferences'] and not media['audioFailures']
assert (reg['workshops'],reg['exams'],reg['englishQuestions'],reg['frenchQuestions'],reg['numberQuestions'])==(216,12,664,118,97)

bugs=[
 ('P1','Semaine 1 et examen inaccessibles','Le paramètre de route « 0 » était une chaîne ; le contrôle strict le traitait comme une semaine verrouillée.','Conversion et validation des identifiants numériques. La semaine 1 ouvre immédiatement ; la semaine 2 reste verrouillée avant validation.'),
 ('P1','Médias cherchés dans le mauvais dossier','Des préfixes ../../ étaient supprimés ; les copies locales des médias de cours sont incomplètes.','Résolution commune vers assets à la racine, pour données embarquées, JSON, phonèmes et anciens gabarits.'),
 ('P1','Chargement du cours voisin en erreur','Depuis un sous-dossier de cours, le JSON de l’autre matière était demandé au mauvais emplacement.','Construction des deux URL depuis la racine de l’application et adaptation récursive des chemins reçus.'),
 ('P1','Lecteur anglais cassé après chargement du français','Le remplacement de DATA.books supprimait le livre anglais ; le lecteur ne retrouvait plus son nom.','Fusion par identifiant de livre ; reconstruction de la liste des pages et de leur index.'),
 ('P1','Erreurs pendant les réussites et la fin du bilan','playSuccessChimeAndCheer et fireConfetti étaient appelées sans définition dans les versions testées.','Ajout de ces fonctions à partir des effets existants. Les effets décoratifs respectent la réduction des mouvements.'),
 ('P1','Cinq questions YLE yes/no inutilisables','Les réponses et choix manquaient dans les données ; le mélange des choix levait une exception.','Ajout des choix yes/no et de la réponse indiquée par chaque modèle, dans la source JSON et les secours embarqués.'),
 ('P2','Écoute de l’histoire Where’s Amy interrompue','Les apostrophes du récit produisaient du JavaScript HTML invalide.','Remplacement des gestionnaires audio concernés par des attributs de données et un raccordement JavaScript.'),
 ('P2','Programme anglais incohérent selon le point d’entrée','Une leçon référençait une unité absente, deux mots manquaient, et le secours français ne contenait que 38 leçons anglaises.','Correction de review-one, ajout de bat et scooter avec leurs images existantes, synchronisation des 53 leçons et 664 questions dans les trois pages.'),
 ('P2','Dix images encore utilisées avaient été archivées','Des illustrations de vocabulaire n’étaient plus présentes dans les médias actifs.','Restauration des dix fichiers originaux depuis archives-html/old-assets, sans génération de nouvelles illustrations.'),
 ('P2','Grande écriture et contraste sans effet fiable','Les commandes écrivaient des champs différents de ceux lus par les préférences et la validation des exports.','Utilisation des champs size et contrast attendus ; contrôle du rendu et de la validité des sauvegardes.'),
 ('P2','Actions différées dans une ancienne activité','Des délais de narration, de réussite ou d’avancement pouvaient agir après navigation ou changement de profil.','Vérification de l’identité de séance, de la route et du profil ; nettoyage des anciens états et fenêtres de réussite ; garde contre les validations répétées du bilan.'),
 ('P2','Écouteurs de dessin conservés après remplacement du canevas','Les écouteurs globaux de fin de geste étaient ajoutés à chaque atelier ou question écrite.','Retrait des anciens écouteurs avant remplacement du canevas et au changement de route.'),
 ('P2','Bibliothèque, anciens liens et compteurs trompeurs','Le filtre « Tout le livre · 98 pages » affichait aussi le guide et l’anglais ; la reprise pouvait ouvrir un autre cours ; quatre anciens liens vers la deuxième partie ouvraient une page introuvable.','98 pages françaises par défaut, reprise limitée au français, compatibilité des anciens liens 0-64/72/80/88 vers les bonnes pages du second fichier, compteurs réels du livre et des activités.'),
 ('P2','Arabe affiché avec des métadonnées françaises','Après sélection de l’arabe, html restait lang=fr et dir=ltr.','Langue et direction de la navigation synchronisées ; contenu anglais conservé en anglais et de gauche à droite.'),
 ('P2','Débordement et titre superposé sur mobile','À 390 px, la page de semaine débordait ; le titre se comprimait sous les commandes de son et de langue.','Pistes de grille réductibles, cartes et aperçu oral adaptables, titre sur une ligne dédiée, commandes d’en-tête plus hautes. Largeur finale du document : 375 px pour 390 px de fenêtre, avec barre de défilement.'),
 ('P2','Serveur local fragile pour les URL et médias','Une URL mal encodée pouvait interrompre le traitement ; le confinement des chemins était incomplet ; les plages de lecture n’étaient pas gérées.','Réponses 400/403/404 contrôlées, validation des chemins, HEAD, plages 206/416 et écoute IPv4 locale. Tests sans arrêt du serveur de prévisualisation.'),
 ('P3','Le bilan des tests promettait une stabilité absolue','Cinq suites passantes affichaient « 100% stable, sécurisée et conforme » malgré des bugs reproduits dans le navigateur.','Sept suites maintenant raccordées à npm test ; message final limité aux scénarios réellement contrôlés.'),
]

recommendations=[
 ('Priorité 1 — Un accueil enfant très simple','Sur la capture du portail, plusieurs matières et de longs textes se disputent l’attention. Proposer trois grandes entrées : « Je continue », « Je joue », « Mon livre ». Garder les huit rubriques détaillées et les réglages dans un accès adulte.'),
 ('Priorité 1 — Une consigne courte, disponible à l’oral','La page de semaine expose les activités de toute la semaine. Montrer d’abord la prochaine petite action ; conserver le plan complet pour l’adulte. Exemple : « Écoute. Puis touche les images où tu entends a. » Ajouter une démonstration rejouable, avec un bouton Arrêter toujours accessible.'),
 ('Priorité 1 — Séparer écouter et répondre','Dans les examens, un même choix comporte un libellé « Écouter » tout en validant la réponse. Donner deux commandes explicites : un haut-parleur pour écouter, puis la carte pour répondre. Éviter qu’un enfant soumette une réponse en voulant seulement l’entendre.'),
 ('Priorité 1 — Distinguer entraînement et maîtrise','Les tracés sont actuellement déclaratifs, sans reconnaissance automatique de l’écriture. Des exercices peuvent être aidés ou corrigés avant validation. Afficher « Activité terminée » pour l’entraînement ; réserver « Réussi seul » ou une appréciation de tracé à une observation explicite de l’adulte. Garder les notes sur 20 dans l’espace adulte et proposer des étapes visuelles à l’enfant.'),
 ('Priorité 2 — Des séances courtes et une pause volontaire','Conserver la pause déjà présente et offrir des missions de trois à cinq petits défis, ajustables par l’adulte. Éviter les changements de question trop rapides ; privilégier un bouton Continuer lorsque l’enfant a besoin de réécouter. Ces durées sont une proposition à tester avec les enfants, pas une norme médicale.'),
 ('Priorité 2 — De grandes zones tactiles et des repères constants','La capture mobile corrigée garde encore beaucoup de commandes. Viser des zones principales d’au moins 48 × 48 px, avec espacement, un bouton Retour constant, une icône et un mot. Le repère W3C renforcé est 44 × 44 px, sous réserve de ses exceptions ; 48 px est ici un choix de conception pour ce public.'),
 ('Priorité 2 — Clarifier les langues','Choisir avec le parent la langue des consignes et distinguer ce réglage de la matière étudiée. Exemple : navigation et aide en français ou arabe, mots et modèles anglais en anglais. Compléter les traductions partielles visibles dans le cours anglais, et conserver des enregistrements pour les consignes essentielles.'),
 ('Priorité 2 — Des mouvements discrets et désactivables','Conserver les retours de réussite, mais limiter les sauts, particules et déplacements automatiques à de très courts moments. Respecter le choix système et le réglage familial. GSAP peut servir ponctuellement ; une intégration de Lenis, SplitText ou d’effets de défilement n’est pas nécessaire pour les exercices de lecture.'),
 ('Priorité 3 — Une base technique commune','Les trois HTML embarquent encore des moteurs proches. Centraliser progressivement le moteur, les données et les médias pour éviter les divergences observées. Mesurer le démarrage sur une tablette modeste avant d’ajouter des bibliothèques ou une migration React.'),
]

limits=[
 'Les parcours automatisés s’exécutent dans un DOM isolé (jsdom). Le stockage, les dialogues, le son et le dessin y sont simulés ; ces résultats vérifient le code et les états, pas le matériel de l’utilisateur.',
 'Les 4 326 fichiers audio ont été décodés par FFmpeg, soit 1 442 contenus binaires distincts après déduplication. Il ne s’agit pas d’une écoute humaine intégrale. La prononciation de chaque phonème, l’intonation et l’adéquation pédagogique doivent être revues avec un enseignant.',
 'Dans le vrai navigateur : 98 pages françaises et 115 pages anglaises parcourues ; lecture d’un phonème observée avec durée et temps de lecture ; validation mathématique, pause/reprise et maintien de la progression après rechargement ; retours au portail ; changement de langue ; écran de 390 px.',
 'Le geste manuscrit complet, le téléchargement de chaque dessin, l’impression papier, une panne réelle d’IndexedDB et un test sur de vraies tablettes Android/iPad ne sont pas couverts par ces preuves. Les boutons de validation des tracés n’analysent pas la forme des lettres.',
 'Le secours de données sans réseau et la réduction des particules ont été testés séparément en simulation. Cela ne garantit pas une voix de synthèse hors ligne sur tous les appareils ni un stockage partagé entre fichiers ouverts en file://.',
 'Les quatre liens externes de crédits (modèles Piper et jeux de données SIWIS/LJ Speech) ont été ouverts séparément ; les services tiers ne sont pas contrôlés par le site. Les sources PDF archivées, anciens backups et contenus annoncés « bientôt » ne sont pas considérés comme des cours fonctionnels à corriger.',
 'Aucune certification WCAG, mesure de performance avant/après, validation exhaustive des contenus scolaires ou séance d’observation avec de jeunes enfants n’est annoncée.',
 'Des modifications simultanées ont été constatées pendant l’audit et conservées à la demande de l’utilisateur. Les empreintes finales ci-dessous identifient la version vérifiée ; toute modification ultérieure demande de rejouer les tests concernés.',
]

rows=[]
for p in dom['pages']:
 rows.append((p['file'],len(p['routes']),len(p['buttons']),p['audioCalls'],len(p['errors'])))
metrics={'date':'2026-11-15','root':str(ROOT),'npmSuites':7,'routes':sum(r[1] for r in rows),'buttonActivations':sum(r[2] for r in rows),'audioFiles':media['audioFiles'],'audioUnique':media['uniqueAudioContents'],'dataMediaReferences':media['references'],'questions':{'workshops':216,'exams':12,'english':664,'french':118,'math':97},'pages':[{ 'file':p['file'],'sha256':p['testedHash']} for p in dom['pages']]}
(OUT/'summary.json').write_text(json.dumps(metrics,ensure_ascii=False,indent=2),encoding='utf-8')

intro='Audit du 15 novembre 2026 — Mon École en Poche. Les bugs reproduits et corrigés sont détaillés ci-dessous. Les améliorations proposées pour les enfants sont séparées des changements déjà appliqués.'
coverage=f"Sept suites npm test validées, puis contre-tests ciblés des derniers correctifs du compteur anglais et des anciens liens du livre français. {metrics['routes']} rendus de routes et {metrics['buttonActivations']} activations de boutons/commandes sur les trois points d’entrée ; ces totaux comprennent des écrans et commandes répétés. Aucun échec JavaScript, média local absent ou requête JSON locale en échec dans le parcours final."
md=['# Rapport fonctionnel — Mon École en Poche','',intro,'','## Résultat et couverture','',coverage,'',f"**Validations :** 216 ateliers, 12 examens, 118 questions de lecture française, 664 questions anglaises et 97 questions de nombres. **Médias :** {media['references']} références de données résolues ; 4 326 fichiers audio décodés sans erreur. **Navigateur :** 98 pages françaises et 115 pages anglaises affichées sans image cassée.",'','| Point d’entrée | Routes rendues | Activations | Appels audio simulés | Erreurs JS |','|---|---:|---:|---:|---:|']
